CREATE TABLE IF NOT EXISTS ref_dish_modifiers (id SERIAL PRIMARY KEY, suffix VARCHAR(255) NOT NULL, sort_index INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ref_breakfast_names (id SERIAL PRIMARY KEY, base_name VARCHAR(240) NOT NULL, sort_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ref_lunch_pairs (id SERIAL PRIMARY KEY, protein_part VARCHAR(200) NOT NULL, garnish_part VARCHAR(200) NOT NULL, sort_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ref_lunch_proteins (id SERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, sort_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ref_grain_garnishes (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, sort_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ref_dinner_names (id SERIAL PRIMARY KEY, name VARCHAR(300) NOT NULL, sort_index INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ref_snacks (id SERIAL PRIMARY KEY, name VARCHAR(300) NOT NULL, allergens VARCHAR(100)[] NOT NULL DEFAULT '{}', sort_index INTEGER NOT NULL);
TRUNCATE ref_dish_modifiers, ref_breakfast_names, ref_lunch_pairs, ref_lunch_proteins, ref_grain_garnishes, ref_dinner_names, ref_snacks RESTART IDENTITY CASCADE;

